cssCode:
.cinematic-text {
  font-size: 32px; font-weight: 900; font-family: serif;
  color: transparent; letter-spacing: 5px; text-align: center;
  -webkit-text-stroke: 1px rgba(255,255,255,0.3);
  background: linear-gradient(to right, #ffffff, #a855f7);
  -webkit-background-clip: text; background-clip: text;
  opacity: 0; transform: scale(0.8);
  transition: all 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.cinematic-text.show {
  opacity: 1; transform: scale(1);
  text-shadow: 0 0 60px rgba(168,85,247,0.9);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;';
c.innerHTML = `
  <div style="height: 200vh; position: relative;">
    <div style="position: sticky; top: 0; height: 100vh; display: flex; align-items: center; justify-content: center; flex-direction: column;">
      <div style="color: #555; font-family: sans-serif; margin-bottom: 20px;">SCROLL DOWN ↓</div>
      <div id="cine-text" class="cinematic-text">BORN OF MOTIONZYNC</div>
    </div>
  </div>
`;
c.addEventListener('scroll', () => {
  const txt = document.getElementById('cine-text');
  if(c.scrollTop > 80) {
    txt.classList.add('show');
  } else {
    txt.classList.remove('show');
  }
});
